templates.manifest:
{
  "schema": "halalpilot/case-manifest@1",
  "_comment": "Written by halalpilot-evidence-clerk. Paths are relative to the case folder. Every fact: status EXTRACTED|OBSERVED + source, or status NEEDS_REVIEW + reason. Never fill a value you cannot see.",
  "case_id": "<kebab-case-business-name>",
  "as_of": "YYYY-MM-DD",
  "business": {
    "name":      { "value": "<as written>", "source": "DOC-001", "status": "EXTRACTED" },
    "address":   { "value": null, "source": null, "status": "NEEDS_REVIEW", "reason": "No document states the premise address" },
    "food_handlers": { "value": "<as written>", "source": "DOC-001", "status": "EXTRACTED" }
  },
  "documents": [
    { "doc_id": "DOC-001", "path": "nota-pemilik.txt", "type": "owner_note", "readable": true, "summary": "<one line>" },
    { "doc_id": "DOC-002", "path": "photos/blurred.jpg", "type": "photo", "readable": false, "summary": "Too blurred to read; nothing extracted" }
  ],
  "products": [
    {
      "product_id": "P1", "name": "<as written>", "source": "DOC-00x", "status": "EXTRACTED",
      "ingredients": [
        { "ingredient_id": "P1-I01", "name": "<as written>", "quantity": "<as written>", "source": "DOC-00x", "status": "EXTRACTED" },
        { "ingredient_id": "P1-I02", "name": "<as written>", "quantity": null, "source": "DOC-00x", "status": "NEEDS_REVIEW", "reason": "Recipe says 'sikit' with no amount" }
      ]
    }
  ],
  "suppliers": [
    { "supplier_id": "S1", "name": "<as written on invoice>", "source": "DOC-00x", "status": "EXTRACTED" }
  ],
  "invoice_lines": [
    { "line_id": "L1", "doc_id": "DOC-00x", "supplier_id": "S1", "item": "<as written>", "code": "<as written or null>", "brand": "<as written or null>", "date": "YYYY-MM-DD", "source": "DOC-00x", "status": "EXTRACTED" }
  ],
  "certificates": [
    { "cert_id": "C1", "doc_id": "DOC-00x", "holder": "<as written>", "certificate_no": "<as written>", "issuer": null, "products_covered": ["<as written>"], "expiry_date": "YYYY-MM-DD", "sample_or_fictional_marking": false, "source": "DOC-00x", "status": "EXTRACTED" }
  ],
  "photo_observations": [
    { "obs_id": "O1", "doc_id": "DOC-00x", "text": "<only what is visible>", "source": "DOC-00x", "status": "OBSERVED" }
  ],
  "needs_review": [
    { "nr_id": "NR-01", "about": "<field or item>", "reason": "<what is missing and where it would come from>", "source": null, "status": "NEEDS_REVIEW" }
  ]
}

templates.matrix:
{
  "schema": "halalpilot/ingredient-matrix@1",
  "_comment": "Written by halalpilot-ingredient-investigator. Exactly one row per manifest ingredient_id. cert_expiry is copied from the manifest, never re-typed from memory.",
  "as_of": "YYYY-MM-DD",
  "rows": [
    {
      "ingredient_id": "P1-I01", "product_id": "P1", "ingredient": "<manifest name>",
      "risk_level": "LOW|MEDIUM|HIGH", "risk_reason": "<why, citing risk-ingredients.md row>",
      "supplier_id": "S1", "invoice_line_id": "L1",
      "cert_id": "C1", "cert_expiry": "YYYY-MM-DD",
      "verdict": "VERIFIED|EXPIRING|EXPIRED|MISMATCH|NO_CERT|LOW_RISK_NO_CERT|NEEDS_REVIEW",
      "evidence": ["DOC-00x", "DOC-00y"],
      "reason": "<required when verdict is NEEDS_REVIEW>",
      "actions": ["Verify certificate <no> in the official halal directory"]
    }
  ],
  "supplier_requests": [
    {
      "request_id": "SR-01", "supplier_id": "S1", "cert_id": "C1",
      "reason": "Certificate expired on YYYY-MM-DD",
      "draft_message": "<polite message asking for the renewed certificate, in the owner's language>"
    }
  ],
  "substitute_suggestions": [
    { "ingredient_id": "P1-I0x", "suggestion": "<generic guidance, e.g. 'ask for a certified plant-based E471'>", "status": "NEEDS_REVIEW", "reason": "No certified alternative supplier is documented in the folder; owner must source one" }
  ]
}

templates.process:
{
  "schema": "halalpilot/process-pack@1",
  "_comment": "Written by halalpilot-process-builder. Everything you author is DRAFT_FOR_OWNER. based_on lists the doc_ids the draft reflects. Missing business documents are NEEDS_REVIEW with a reason.",
  "flows": [
    {
      "product_id": "P1",
      "steps": [
        { "step_no": 1, "name": "Receiving", "description": "<what happens>", "halal_control_point": true,
          "control": "Check halal logo/cert on every delivery against the approved ingredient list", "based_on": ["DOC-00x"], "status": "DRAFT_FOR_OWNER" },
        { "step_no": 2, "name": "<step>", "description": "<what happens>", "halal_control_point": false,
          "control": null, "based_on": [], "status": "NEEDS_REVIEW", "reason": "Recipe does not say how jars are sterilised" }
      ]
    }
  ],
  "procedures": [
    { "sop_id": "SOP-01", "title": "Receiving and storage of ingredients", "purpose": "<one line>",
      "steps": ["<imperative step>"], "records": ["Receiving log"], "based_on": ["DOC-00x"], "status": "DRAFT_FOR_OWNER" }
  ],
  "halal_policy_draft": { "text": "<short policy statement for the owner to sign>", "status": "DRAFT_FOR_OWNER" },
  "missing_documents": [
    { "md_id": "MD-01", "checklist_id": "D01", "document": "Business registration (SSM)", "reason": "Owner note says it exists but no copy is in the folder",
      "owner_action": "Upload a copy of the SSM certificate", "blocking": true, "source": "DOC-001", "status": "NEEDS_REVIEW" }
  ]
}
